/**
 * «Моя повестка» — the personal, cross-cutting queue. /limits and /requests
 * stay the domain views; this one answers a different question: what do *I*
 * owe right now, whatever object it hangs off.
 *
 * Rows are generated by the database (migration 0024) and close themselves
 * when their object moves on, so there is no bulk-complete here — only
 * bulk-OPEN, which is the action a queue actually needs. A row is opened by
 * clicking it; the bulk bar appears only once something is ticked.
 */

import { useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { ChevronRight, ExternalLink } from 'lucide-react'

import {
  Badge,
  Button,
  Callout,
  Card,
  EmptyState,
  Field,
  PageHeader,
  Select,
  Spinner,
} from '../../components/ui'
import { EM_DASH, formatDue } from '../../lib/format'
import { contextFor, subjectFor, useAgendaTasks, useCompleteTask, useTaskSubjects } from './api'
import {
  applyFilters,
  canCompleteByHand,
  displayTaskType,
  formatTaskParams,
  groupTasks,
  isOverdue,
  NO_FILTERS,
  OBJECT_FILTERS,
  presentValues,
  taskLink,
  taskTitleKey,
} from './catalogue'
import type { AgendaFilters, AgendaGroup } from './catalogue'
import { TASK_TYPES } from './types'
import type { Task, TaskObjectType, TaskType } from './types'

/** The group's mark is a left edge, never a fill: a page of pink boxes reads
 * as an error page, and the red due chip already says which row is late. */
const GROUP_EDGE: Record<AgendaGroup, string> = {
  overdue: 'border-l-neg-500',
  urgent: 'border-l-warn-500',
  high: 'border-l-brand-orange/60',
  normal: 'border-l-transparent',
}

export function AgendaPage() {
  const { t, i18n } = useTranslation()
  const { data: tasks, isLoading, isError, dataUpdatedAt } = useAgendaTasks()
  const { data: subjects } = useTaskSubjects(tasks)
  const complete = useCompleteTask()

  const [filters, setFilters] = useState<AgendaFilters>(NO_FILTERS)
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set())
  const [actionError, setActionError] = useState<string | null>(null)

  // One clock for the whole board, taken when the rows were fetched, so a
  // task cannot be overdue in its badge and on time in its group.
  const now = useMemo(() => new Date(dataUpdatedAt || Date.now()), [dataUpdatedAt])

  const all = useMemo(() => tasks ?? [], [tasks])
  const visible = useMemo(() => applyFilters(all, filters), [all, filters])
  const sections = useMemo(() => groupTasks(visible, now), [visible, now])
  const typeOptions = useMemo(() => presentValues(TASK_TYPES, all, (task) => task.task_type), [all])
  const objectOptions = useMemo(() => presentValues(OBJECT_FILTERS, all, (task) => task.object_type), [all])

  const toggle = (id: string) => {
    setSelected((current) => {
      const next = new Set(current)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const selectedLinks = visible
    .filter((task) => selected.has(task.id))
    .map(taskLink)
    .filter((href): href is string => href !== null)

  const openSelected = () => {
    for (const href of selectedLinks) {
      window.open(href, '_blank', 'noopener')
    }
  }

  const runComplete = async (task: Task) => {
    setActionError(null)
    try {
      await complete.mutateAsync(task.id)
      setSelected((current) => {
        const next = new Set(current)
        next.delete(task.id)
        return next
      })
    } catch {
      setActionError(t('agenda.completeFailed'))
    }
  }

  if (isLoading) return <Spinner label={t('common.loading')} />

  const filtered = Boolean(filters.taskType || filters.objectType)

  return (
    <div>
      <PageHeader title={t('agenda.title')} subtitle={t('agenda.subtitle')} />

      <div className="space-y-3 empty:hidden [&:not(:empty)]:mb-5">
        {isError && <Callout tone="neg" title={t('agenda.loadFailed')} />}
        {actionError && <Callout tone="neg" title={actionError} />}
      </div>

      {all.length > 0 && (
        <Card className="mb-5 flex flex-wrap items-end gap-3 p-4">
          <Field label={t('agenda.filters.taskType')} className="min-w-56">
            <Select
              value={filters.taskType}
              onChange={(e) => setFilters((f) => ({ ...f, taskType: e.target.value as TaskType | '' }))}
            >
              <option value="">{t('agenda.filters.anyType')}</option>
              {typeOptions.map(({ value, count }) => (
                <option key={value} value={value}>
                  {t(`agenda.taskTypes.${value}`)} ({count})
                </option>
              ))}
            </Select>
          </Field>
          <Field label={t('agenda.filters.objectType')} className="min-w-56">
            <Select
              value={filters.objectType}
              onChange={(e) => setFilters((f) => ({ ...f, objectType: e.target.value as TaskObjectType | '' }))}
            >
              <option value="">{t('agenda.filters.anyObject')}</option>
              {objectOptions.map(({ value, count }) => (
                <option key={value} value={value}>
                  {t(`agenda.objectTypes.${value}`)} ({count})
                </option>
              ))}
            </Select>
          </Field>
          {filtered && (
            <Button variant="ghost" onClick={() => setFilters(NO_FILTERS)}>
              {t('agenda.filters.reset')}
            </Button>
          )}
        </Card>
      )}

      {/* The bulk action exists only while there is something to act on. */}
      {selectedLinks.length > 0 && (
        <div
          role="region"
          aria-label={t('agenda.selected', { count: selectedLinks.length })}
          className="sticky top-20 z-10 mb-4 flex flex-wrap items-center gap-3 rounded-lg border border-accent-200 bg-accent-50 px-4 py-2.5 shadow-card"
        >
          <span className="text-[13px] font-medium text-accent-700">
            {t('agenda.selected', { count: selectedLinks.length })}
          </span>
          <span className="flex-1" />
          <Button variant="ghost" size="sm" onClick={() => setSelected(new Set())}>
            {t('agenda.clearSelection')}
          </Button>
          <Button size="sm" onClick={openSelected} title={t('agenda.openSelectedHint')}>
            <ExternalLink aria-hidden />
            {t('agenda.openSelected', { count: selectedLinks.length })}
          </Button>
        </div>
      )}

      {sections.length === 0 ? (
        <EmptyState
          title={filtered ? t('agenda.empty.filtered') : t('agenda.empty.title')}
          // The reset button sits in the filter bar above; offered once.
          hint={filtered ? t('agenda.empty.filteredHint') : t('agenda.empty.hint')}
        />
      ) : (
        <div className="flex flex-col gap-5">
          {sections.map((section) => (
            <section key={section.group}>
              <h2
                className={`mb-2 flex items-center gap-2 text-sm font-semibold ${
                  section.group === 'overdue' ? 'text-neg-500' : 'text-slate-700'
                }`}
              >
                {t(`agenda.groups.${section.group}`)}
                <span className="num text-xs font-normal text-slate-400">{section.tasks.length}</span>
              </h2>
              <Card className="overflow-hidden">
                <ul className="divide-y divide-slate-100">
                  {section.tasks.map((task) => (
                    <TaskRow
                      key={task.id}
                      task={task}
                      edge={GROUP_EDGE[section.group]}
                      subject={subjectFor(task, subjects)}
                      context={contextFor(task, subjects)}
                      locale={i18n.language}
                      now={now}
                      checked={selected.has(task.id)}
                      onToggle={() => toggle(task.id)}
                      onComplete={() => void runComplete(task)}
                      completing={complete.isPending}
                    />
                  ))}
                </ul>
              </Card>
            </section>
          ))}
        </div>
      )}
    </div>
  )
}

interface TaskRowProps {
  task: Task
  edge: string
  subject: string | null
  context: string | null
  locale: string
  now: Date
  checked: boolean
  onToggle: () => void
  onComplete: () => void
  completing: boolean
}

function TaskRow({
  task,
  edge,
  subject,
  context,
  locale,
  now,
  checked,
  onToggle,
  onComplete,
  completing,
}: TaskRowProps) {
  const { t } = useTranslation()
  const href = taskLink(task)
  const overdue = isOverdue(task, now)
  const title = t(taskTitleKey(task, now), {
    ...formatTaskParams(task.params, locale),
    subject: subject ?? EM_DASH,
  })

  const body = (
    <>
      <span className="min-w-0 flex-1">
        <span className="block text-sm font-medium text-slate-900">{title}</span>
        <span className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-1 text-[13px] text-slate-500">
          <Badge tone="neutral">{t(`agenda.taskTypes.${displayTaskType(task, now)}`)}</Badge>
          {context && <span className="min-w-0 truncate">{context}</span>}
        </span>
      </span>
      {task.due_at && (
        <span className="shrink-0 pt-0.5">
          <Badge tone={overdue ? 'neg' : 'neutral'}>
            {t(overdue ? 'agenda.overdueSince' : 'agenda.dueBy', { moment: formatDue(task.due_at, locale) })}
          </Badge>
        </span>
      )}
      {href && <ChevronRight className="mt-0.5 size-4 shrink-0 text-slate-300 group-hover:text-accent-500" />}
    </>
  )

  return (
    <li className={`flex items-stretch border-l-[3px] ${edge} transition-colors hover:bg-accent-50/50`}>
      {/* The tick box is a cell of its own, outside the link: a checkbox
          inside an <a> is invalid and would navigate on every tick. */}
      <label className="flex shrink-0 cursor-pointer items-start py-3.5 pr-1 pl-4">
        <input
          type="checkbox"
          checked={checked}
          onChange={onToggle}
          disabled={!href}
          aria-label={t('agenda.selectRow')}
          className="mt-0.5 size-4 rounded border-slate-300 accent-accent-600 disabled:opacity-40"
        />
      </label>
      {href ? (
        <Link to={href} className="group flex min-w-0 flex-1 items-start gap-3 py-3 pr-4 pl-2">
          {body}
        </Link>
      ) : (
        <div className="flex min-w-0 flex-1 items-start gap-3 py-3 pr-4 pl-2">{body}</div>
      )}
      {canCompleteByHand(task.task_type) && (
        <div className="flex shrink-0 items-start py-2.5 pr-4">
          <Button variant="secondary" size="sm" disabled={completing} onClick={onComplete}>
            {t('agenda.markDone')}
          </Button>
        </div>
      )}
    </li>
  )
}
